#include "stdlib/math/base/special/sqrt1pm1f.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/log1pf.h"
#include "stdlib/math/base/special/sqrtf.h"
#include "stdlib/math/base/special/absf.h"

/**
* Define prototypes for external functions.
*/
extern float expm1f( float x );

/**
* Computes the value of `sqrt(1+x)-1` for a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_sqrt1pm1f( 3.0f );
* // returns 1.0f
*/
float stdlib_base_sqrt1pm1f( const float x ) {
	if ( stdlib_base_is_nanf( x ) ) {
		return 0.0f / 0.0f; // NaN
	}
	if ( stdlib_base_absf( x ) > 0.75f ) {
		return stdlib_base_sqrtf( 1.0f + x ) - 1.0f;
	}
	return expm1f( stdlib_base_log1pf( x ) / 2.0f );
}
